+import { verifyAuthenticationResponse } from "@simplewebauthn/server";
+import { db } from "@/lib/db";
+
+const RP_ID = process.env.RP_ID ?? "app.studio-nord.fr";
+
+export async function verifyPasskey(user: UserWithPasskeys, assertion: PasskeyAssertion) {
+  const key = user.passkeys.find((k) => k.credentialId === assertion.id);
+  if (!key) return false;
+  const { verified, authenticationInfo } = await verifyAuthenticationResponse({
+    response: assertion,
+    expectedChallenge: await takeChallenge(user.id),
+    expectedOrigin: `https://${RP_ID}`,
+    expectedRPID: RP_ID,
+    credential: { id: key.credentialId, publicKey: key.publicKey, counter: key.counter },
+  });

